using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "HiveModuleOmenData", menuName = "Data/Battle/Omens System/Omen Data/Austra/HiveModuleOmenData")]
public class HiveModuleOmenData : OmenData
{
	[Header("HiveModule Omen")]
	[SerializeField]
	private int additionalCriticalChance;

	[SerializeField]
	private int additionalCriticalMultiplier;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.HiveModuleOmenActive = true;
		ReferenceSingleton<AustraOmensHandler>.Instance.HiveModuleOmenCriticalMultiplierAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			return additionalCriticalMultiplier;
		};
		ReferenceSingleton<AustraOmensHandler>.Instance.HiveModuleOmenChanceAction = () => additionalCriticalChance;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.HiveModuleOmenActive = false;
		ReferenceSingleton<AustraOmensHandler>.Instance.HiveModuleOmenChanceAction = null;
		ReferenceSingleton<AustraOmensHandler>.Instance.HiveModuleOmenCriticalMultiplierAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(base.OmenConvertedDescription(), additionalCriticalChance, additionalCriticalMultiplier);
	}
}
